CREATE OR REPLACE FUNCTION public.is_plan_member(_plan uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.plans WHERE id=_plan AND (host_id=_user OR (is_private AND _user=ANY(private_participants)))) OR EXISTS(SELECT 1 FROM public.join_requests WHERE plan_id=_plan AND user_id=_user AND status='approved') $$;
CREATE FUNCTION public.guard_private_join() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.plans WHERE id=NEW.plan_id AND is_private AND NOT NEW.user_id=ANY(private_participants) AND host_id<>NEW.user_id) THEN RAISE EXCEPTION 'This plan is private'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_private_join BEFORE INSERT ON public.join_requests FOR EACH ROW EXECUTE FUNCTION public.guard_private_join();
CREATE OR REPLACE FUNCTION public.friends_going(_plan uuid DEFAULT NULL) RETURNS TABLE(plan_id uuid,person_id uuid,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT j.plan_id,p.id,split_part(p.name,' ',1) FROM public.join_requests j JOIN public.profiles p ON p.id=j.user_id JOIN public.plans x ON x.id=j.plan_id WHERE auth.uid() IS NOT NULL AND j.status='approved' AND NOT x.is_private AND public.are_friends(auth.uid(),j.user_id) AND (_plan IS NULL OR j.plan_id=_plan) $$;
CREATE OR REPLACE FUNCTION public.similar_people(_city text,_interests text[],_activity text DEFAULT '',_level text DEFAULT '') RETURNS SETOF public.profiles LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.* FROM public.profiles p WHERE auth.uid() IS NOT NULL AND p.id<>auth.uid() AND p.onboarded AND NOT public.people_blocked(auth.uid(),p.id) AND lower(p.home_city)=lower(_city) AND p.interests && _interests AND (_level='' OR _level='any' OR (EXISTS(SELECT 1 FROM public.user_settings s WHERE s.user_id=auth.uid() AND s.demo_plus) AND EXISTS(SELECT 1 FROM public.interest_levels l WHERE l.user_id=p.id AND l.interest=_activity AND l.level=_level))) ORDER BY cardinality(ARRAY(SELECT unnest(p.interests) INTERSECT SELECT unnest(_interests))) DESC LIMIT 12 $$;